def transform(grid):
    n=len(grid); rows=[r[0] for r in grid]
    period=n
    for p in range(1,n+1):
        known={} ; ok=True
        for i,v in enumerate(rows):
            if v:
                k=i%p
                if k in known and known[k]!=v: ok=False; break
                known[k]=v
        if ok and p<n:
            period=p; break
    seq={}
    for i,v in enumerate(rows):
        if v: seq[i%period]=v
    return [[seq.get(i%period,0)]*n for i in range(n)]

